56	function logAgentRun(entry) {
57	  const estimateTokens = (text) => Math.ceil((text || '').length / 4);
58	  const estimateCost = (i, o) => (i * 3 + o * 15) / 1_000_000;
59	  const inputTokens = estimateTokens(entry.prompt || '');
60	  const outputTokens = estimateTokens(entry.output || '');
61	  const run = {
62	    id: Date.now().toString(36) + Math.random().toString(36).slice(2, 7),
63	    agentName: entry.agentName || 'unknown',
64	    prompt: (entry.prompt || '').slice(0, 200),
65	    source: entry.source || 'unknown',
66	    timestamp: new Date().toISOString(),
67	    duration: entry.duration || 0,
68	    status: entry.status || 'success',
69	    promptChars: (entry.prompt || '').length,
70	    outputChars: (entry.output || '').length,
71	    estimatedTokens: inputTokens + outputTokens,
72	    estimatedCost: estimateCost(inputTokens, outputTokens),
73	    error: entry.error || null,
74	    metadata: entry.metadata || {},
75	  };
76	  try { db.insertAgentRun(run); } catch (err) { console.error('[logAgentRun] DB insert failed:', err.message); }
77	  return run;
78	}
