80	function buildScheduledPrompt(schedule) {
81	  let instructions = '';
82	  const globalAgentsDir = path.join(CLAUDE_DIR, 'agents');
83	  if (fs.existsSync(globalAgentsDir)) {
84	    for (const file of fs.readdirSync(globalAgentsDir).filter(f => f.endsWith('.md'))) {
85	      const fname = file.replace('.md', '');
86	      if (fname === schedule.agentName || fname.toLowerCase() === schedule.agentName.toLowerCase()) {
87	        instructions = fs.readFileSync(path.join(globalAgentsDir, file), 'utf-8');
88	        break;
89	      }
90	    }
91	  }
92	  if (instructions) {
93	    return `${instructions}\n\n---\n\n## Task:\n${schedule.prompt}\n\n---\n\nIMPORTANT: Produce the actual deliverable directly. Do NOT write meta-commentary. Output only the finished work product.`;
94	  }
95	  return schedule.prompt;
96	}
