98	function startScheduleJob(schedule) {
99	  if (activeJobs.has(schedule.id)) { activeJobs.get(schedule.id).stop(); activeJobs.delete(schedule.id); }
100	  if (!schedule.enabled || !cron.validate(schedule.cron)) return;
101	
102	  const job = cron.schedule(schedule.cron, async () => {
103	    const startTime = Date.now();
104	    try {
105	      const prompt = buildScheduledPrompt(schedule);
106	      const output = await runClaudeSync(prompt, 300000);
107	      logAgentRun({ agentName: schedule.agentName, prompt: schedule.prompt, output, source: 'schedule', duration: Date.now() - startTime, status: 'success', metadata: { scheduleId: schedule.id } });
108	      const schedules = loadSchedules();
109	      const idx = schedules.findIndex(s => s.id === schedule.id);
110	      if (idx >= 0) { schedules[idx].lastRunAt = new Date().toISOString(); schedules[idx].lastRunStatus = 'success'; saveSchedules(schedules); }
111	    } catch (err) {
112	      logAgentRun({ agentName: schedule.agentName, prompt: schedule.prompt, output: '', source: 'schedule', duration: Date.now() - startTime, status: 'error', error: err.message, metadata: { scheduleId: schedule.id } });
113	      const schedules = loadSchedules();
114	      const idx = schedules.findIndex(s => s.id === schedule.id);
115	      if (idx >= 0) { schedules[idx].lastRunAt = new Date().toISOString(); schedules[idx].lastRunStatus = 'error'; saveSchedules(schedules); }
116	    }
117	  });
118	  activeJobs.set(schedule.id, job);
119	}
