121	function bootSchedules() {
122	  try {
123	    const schedules = loadSchedules();
124	    let active = 0;
125	    for (const s of schedules) {
126	      if (s.enabled) { startScheduleJob(s); active++; }
127	    }
128	    if (active > 0) console.log(`  Schedules: ${active} active cron job(s) restored`);
129	  } catch {}
130	}
