179	  if (schedules[idx].enabled) startScheduleJob(schedules[idx]);
180	  else if (activeJobs.has(schedules[idx].id)) { activeJobs.get(schedules[idx].id).stop(); activeJobs.delete(schedules[idx].id); }
181	
182	  res.json(schedules[idx]);
183	});
